// Explicit asset-only UI check. Uses a prior generated PNG for Result; no new AI request.
if(GameObject.Find("UIWeb4Verification"))return "Already running.";
var root=new GameObject("UIWeb4Verification");UnityEngine.Object.DontDestroyOnLoad(root);
Cysharp.Threading.Tasks.UniTask.Void(async()=>{
 var report=new Newtonsoft.Json.Linq.JObject{["task"]="UI-WEB-004"};var checks=new Newtonsoft.Json.Linq.JArray();report["checks"]=checks;
 var manager=UnityEngine.Object.FindFirstObjectByType<Core.GameManager>();var hub=UnityEngine.Object.FindFirstObjectByType<Exhibition.Blocks.RfidReaderHub>();var adapter=UnityEngine.Object.FindFirstObjectByType<Core.KeyboardButtonSimulator>();
 bool wasEnabled=adapter&&adapter.enabled,background=Application.runInBackground;var initial=manager.CurrentLanguage;var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
 using var deadline=new System.Threading.CancellationTokenSource(TimeSpan.FromSeconds(100));var token=deadline.Token;
 void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add(label);}
 async Cysharp.Threading.Tasks.UniTask Frames(int n=5){for(int i=0;i<n;i++)await Cysharp.Threading.Tasks.UniTask.Yield(Cysharp.Threading.Tasks.PlayerLoopTiming.Update,token);}
 async Cysharp.Threading.Tasks.UniTask Ready(){await Cysharp.Threading.Tasks.UniTask.WaitUntil(()=>manager.IsInputReady&&!manager.IsTransitioning&&!manager.IsPresentationLocked&&!manager.IsLanguageChanging&&hub.IsArtworkReady,cancellationToken:token);await Frames();}
 async Cysharp.Threading.Tasks.UniTask Tap(){manager.SetButtonPressed(false);await Frames();manager.SetButtonPressed(true);await Frames();manager.SetButtonPressed(false);await Frames();await Ready();}
 async Cysharp.Threading.Tasks.UniTask Language(Core.SessionLanguage language){await Ready();if(manager.CurrentLanguage==language)return;manager.SetButtonPressed(false);await Frames();manager.SetButtonPressed(true);await Cysharp.Threading.Tasks.UniTask.Delay(2300,Cysharp.Threading.Tasks.DelayType.Realtime,cancellationToken:token);manager.SetButtonPressed(false);await Frames();await Ready();Check(manager.CurrentLanguage==language,"Title language switch: "+language);}
 void Help(string id,string expected){var set=UnityEngine.Object.FindFirstObjectByType<Exhibition.UI.LocalizedImageSet>();var bindings=(Exhibition.UI.LocalizedImageSet.Binding[])set.GetType().GetField("bindings",flags).GetValue(set);var image=System.Array.Find(bindings,b=>b.id==id).image;Check(image&&image.sprite&&image.sprite.name==expected&&image.gameObject.activeInHierarchy&&image.color==Color.white,"Correct visible help: "+id+" / "+expected);}
 void Geometry(){
  var set=UnityEngine.Object.FindFirstObjectByType<Exhibition.UI.LocalizedImageSet>();
  var doc=JsonUtility.FromJson<Exhibition.UI.ImageLanguageDocument>(System.IO.File.ReadAllText("Assets/StreamingAssets/Lang_"+(manager.LanguageCode=="th"?"Th":"En")+".json"));
  var bindings=(Exhibition.UI.LocalizedImageSet.Binding[])set.GetType().GetField("bindings",flags).GetValue(set);
  foreach(var b in bindings){var entry=System.Array.Find(doc.images,e=>e.id==b.id);Check(b.image&&b.image.sprite&&b.image.sprite.name==entry.sprite&&Vector2.Distance(b.image.rectTransform.anchoredPosition,new Vector2(entry.x,-entry.y))<.02f&&Vector2.Distance(b.image.rectTransform.sizeDelta,new Vector2(entry.width,entry.height))<.02f,"Sprite and geometry: "+manager.LanguageCode+" / "+b.id);}
 }
 async Cysharp.Threading.Tasks.UniTask Shot(string name){Geometry();Canvas.ForceUpdateCanvases();await Cysharp.Threading.Tasks.UniTask.WaitForEndOfFrame(UnityEngine.Object.FindFirstObjectByType<Exhibition.UI.LocalizedImageSet>(),token);var shot=ScreenCapture.CaptureScreenshotAsTexture();System.IO.File.WriteAllBytes("docs/validation/ui_web4/"+name+".png",shot.EncodeToPNG());UnityEngine.Object.Destroy(shot);await Frames();}
 try{
  Application.runInBackground=true;if(adapter)adapter.enabled=false;await Ready();
  foreach(var language in new[]{Core.SessionLanguage.Thai,Core.SessionLanguage.English}){
   await Language(language);string code=language==Core.SessionLanguage.Thai?"th":"en";
   Help("idle.help","ButtonHelpBox_"+code);var backgroundImage=System.Linq.Enumerable.FirstOrDefault(UnityEngine.Object.FindObjectsByType<UnityEngine.UI.Image>(FindObjectsSortMode.None),i=>i.sprite&&i.sprite.name=="Intro_bg");Check(backgroundImage&&backgroundImage.color==Color.white&&backgroundImage.sprite.texture.width==1920&&backgroundImage.sprite.texture.height==1080,"Updated full-size Intro_bg is displayed: "+code);await Shot("idle_"+code);
   await Tap();var controller=UnityEngine.Object.FindFirstObjectByType<Exhibition.Blocks.BlockExperienceController>();await Cysharp.Threading.Tasks.UniTask.WaitUntil(()=>controller&&controller.IsReady,cancellationToken:token);
   hub.RecognizeReader(3,Exhibition.Blocks.BlockKind.Group,"student");await Ready();Help("group.help",language==Core.SessionLanguage.Thai?"ButtonHelpBox_groupselect_th":"ButtonHelpBox_groupselectPanel_en");await Shot("group_"+code);
   var groupUI=UnityEngine.Object.FindFirstObjectByType<Exhibition.UI.LocalizedImageSet>().transform;var board=(RectTransform)groupUI.Find("GroupSelection/GroupBoard");Check(board.anchoredPosition==new Vector2(636,-274),"Four-reader board position preserved: "+code);Check(System.Linq.Enumerable.Count(board.GetComponentsInChildren<Exhibition.UI.UIAnimatedElement>(true),e=>e.name.StartsWith("GroupFrame"))==4,"Four animated reader slots preserved: "+code);
   await Tap();hub.RecognizeReader(0,Exhibition.Blocks.BlockKind.Product,"shoes");hub.RecognizeReader(1,Exhibition.Blocks.BlockKind.Color,"red");hub.RecognizeReader(2,Exhibition.Blocks.BlockKind.Color,"blue");await Ready();Check(!controller.IsGenerating,"Resource check does not generate an AI image: "+code);Help("selection.help",language==Core.SessionLanguage.Thai?"ButtonHelpBox_selectall_th":"ButtonHelpBox_selectallPanel_en");await Shot("selection_"+code);
   var texture=new Texture2D(2,2,TextureFormat.RGBA32,false);if(!ImageConversion.LoadImage(texture,System.IO.File.ReadAllBytes("docs/validation/comfy_style3/runtime_0_shoes.png"))||!controller.TryDisplayResult(texture,controller.Selection.Revision)){UnityEngine.Object.Destroy(texture);throw new Exception("Could not attach the prior PNG for UI verification.");}
   await Ready();await Tap();Check(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="2_Result","Normal result transition preserved: "+code);Help("result.help",language==Core.SessionLanguage.Thai?"ButtonHelpBox_recommendedAd_th":"ButtonHelpBox_RecommendedAd_en");await Shot("result_"+code);var playbackHint=UnityEngine.Object.FindFirstObjectByType<Exhibition.UI.ResultVideoController>().GetType().GetField("playbackHint",flags).GetValue(UnityEngine.Object.FindFirstObjectByType<Exhibition.UI.ResultVideoController>()) as GameObject;Check(playbackHint&&!playbackHint.activeSelf,"Video hint hidden on advertisement: "+code);
   var video=UnityEngine.Object.FindFirstObjectByType<Exhibition.UI.ResultVideoController>();await Tap();await Cysharp.Threading.Tasks.UniTask.WaitUntil(()=>video.State==Exhibition.UI.ResultVideoController.ScreenState.Playing,cancellationToken:token);Check((long)typeof(Exhibition.UI.ResultVideoController).GetField("_firstFrame",flags).GetValue(video)==0,"Video frame zero preserved: "+code);
   Check(playbackHint.activeInHierarchy,"Video hint visible during playback: "+code);await Shot("playing_"+code);await Tap();Check(video.State==Exhibition.UI.ResultVideoController.ScreenState.Playing,"Short input does not change video behavior: "+code);
   var player=(UnityEngine.Video.VideoPlayer)typeof(Exhibition.UI.ResultVideoController).GetField("player",flags).GetValue(video);Check(player.clip&&player.clip.name.EndsWith(code),"Language video preserved: "+code);player.time=Math.Max(0,player.length-.25);player.Play();await Cysharp.Threading.Tasks.UniTask.WaitUntil(()=>video.State==Exhibition.UI.ResultVideoController.ScreenState.Finished,cancellationToken:token);await Ready();Check(!playbackHint.activeSelf,"Video hint hidden on completion: "+code);await Shot("end_"+code);
   if(code=="th"){await Tap();}else{manager.SetButtonPressed(true);await Cysharp.Threading.Tasks.UniTask.Delay(5200,Cysharp.Threading.Tasks.DelayType.Realtime,cancellationToken:token);manager.SetButtonPressed(false);await Ready();}Check(manager.IsTitleScreen,"Finished video / five-second home preserved: "+code);
  }
  await Language(initial);report["passed"]=true;
 }catch(Exception ex){report["passed"]=false;report["error"]=ex.ToString();Debug.LogException(ex);}
 finally{if(manager)manager.ResetButtonInput();if(adapter)adapter.enabled=wasEnabled;Application.runInBackground=background;System.IO.File.WriteAllText("docs/validation/ui_web4/runtime.json",report.ToString());UnityEngine.Object.Destroy(root);}
});
return "Web-exported UI assets are being verified in both languages.";
